#include <numeric>     // std::gcd
#include <stdexcept>

// Invariant: den_ > 0 and gcd(|num_|, den_) == 1.
class Fraction {
public:
    Fraction(int n, int d)
        : num_(normalise_num(n, d)), den_(normalise_den(n, d)) {}   // declared order: num_, den_.

    explicit Fraction(int whole) : Fraction(whole, 1) {}  // no silent int -> Fraction.

    int num() const { return num_; }
    int den() const { return den_; }
private:
    static int sign(int d) { return d < 0 ? -1 : 1; }
    static int normalise_num(int n, int d) {
        if (d == 0) throw std::invalid_argument("denominator is zero");
        return sign(d) * n / std::gcd(n, d);
    }
    static int normalise_den(int n, int d) { return sign(d) * d / std::gcd(n, d); }

    int num_;      // initialised first.
    int den_;      // initialised second.
};
// Fraction(2, -4)  ->  num_ = -1, den_ = 2.
// Fraction(1, 0)   ->  throws: no invalid Fraction ever exists.
